-- Mensaje 138 (6-nov-2026) · La bala del re-impulso: las prácticas.
-- 6 guiones (5.8, 5.10, 5.12, 5.13, 5.14 y 5.15). Cada guion se reemplaza solo si está en la versión
-- esperada, y cada nombre solo si es el de hoy; el chequeo del final compara la huella exacta de cada guion y cada nombre, y aborta si algo no quedó.
-- Correrlo dos veces no cambia nada.

UPDATE public.nodes SET practice_script = $g${"notes":"Primer nodo con objeción real. Tres variantes al azar (caro, proveedor de años, consultar con el socio) con espejo de los anti-patrones: defensa, evasión con AIR, cargador vaciado, descuento de pánico y cerrar sin bala. air_a_objecion como critical entrena la distinción central del sistema: la herramienta correcta según la especie del no. v1.1.0 (mensaje 137, Emilio 5-nov): FFF se practica completo, los cinco pasos (entiendo, sintió, encontramos, una bala y cierre con acción); sale la técnica de cuatro pasos (recibe, entiende, responde, avanza), que no está en el Cerebro. v1.1.1 (mensaje 138, Emilio 6-nov): la bala la escoge el vendedor; una ya dicha, aun tal cual, también re-impulsa (ratifica y da seguridad), aunque pegue menos. «Lo que encontramos» de FFF no es la bala.","scope":{"skills_in_focus":["objections.reframe","objections.no_defensivo","objections.bullet_theory"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":8,"max_duration_seconds":180,"min_turns_before_evaluation":2},"phases":{"i_do":{"briefing":"Mira FFF completo ante una objeción real. Cinco pasos: entiendo, sintió, encontramos, una bala, y cierro con acción.\n\nFíjate sobre todo en lo que NO hago: no me defiendo, no cambio de tema, no vacío el cargador.","first_message":"El cliente me dice: «Está caro, el otro me lo da más barato».\n\nEntiendo: «Entiendo cómo se siente, don Ramón; el precio siempre hay que verlo con lupa».\n\nSintió: «A don Aurelio, el de la San José, le pasaba igual al principio».\n\nEncontramos: «Y lo que encontró fue que, sacando la cuenta por servicio, le salía más barato: este rinde once servicios por caja contra ocho del que traía».\n\nUna bala: «Y como paso cada martes, ya no tiene que comprar de más para aguantar la quincena».\n\nCierro con acción: «¿Le armo la primera caja para este martes o para el siguiente?».\n\nCinco pasos, una sola bala, y sin defenderme."},"you_do":{"prompt":"Eres el dueño de un negocio al final de una buena presentación: el vendedor conectó tu dolor (elígelo: faltantes / dinero parado / algo que no consigues) y el producto te interesa GENUINAMENTE — pero tienes una objeción real que necesitas resolver antes de decidir. ELIGE UNA al azar y suéltala clara tras tu primera línea: (A) está caro, comparado con lo que pago ahorita / (B) es que ya tengo proveedor de años, y cambiarle me da cosa / (C) déjeme consultarlo con mi socio, yo no decido solo estas cosas. REGLAS ESPEJO: (1) Si el vendedor hace FFF completo —te entiende sin discutir, te dice que otros sintieron lo mismo y lo que encontraron, te da UNA bala concreta y te propone el siguiente paso—, tu objeción se ablanda: reconoces el punto (pues visto así...) y contestas su pregunta avanzando. Si te responde la objeción y te pide la decisión sin darte ninguna bala (nada positivo que te vuelva a subir el ánimo; lo que encontraron otros clientes no cuenta como bala), contestas con desgano: pues sí, déjeme lo pienso. (2) Si el vendedor SE DEFIENDE (se ofende, discute, justifica atropellado: es que no está caro, es que nosotros somos mejores), te atrincheras: repites la objeción con más firmeza y tu tono se enfría. (3) Si te EVADE con cambio de tema estilo AIR (claro, no se preocupe... oiga qué bien está su local), lo notas y lo dices: oiga, no me cambió el tema — le pregunté por el precio. Tu confianza baja. (4) Si vacía el cargador (dos o más argumentos apilados en una respuesta), te abruma: bueno, bueno, tampoco me eche el rollo completo. (5) Si su bala es vaga o suena a teatro, la retas: ¿a poco? ¿como quién? — si te contesta con algo concreto, lo aceptas; si no, la vaguedad te enfría. (6) Ante el descuento de pánico (si es el caso A), hueles debilidad: ¿entonces sí estaba caro, no? Tu techo: objeción resuelta y decisión avanzando con una condición práctica.","objective":"El vendedor recibe UNA objeción real y hace FFF completo: entiende cómo se siente sin discutir ni defenderse (nunca la evade cambiando de tema), le dice que otros sintieron lo mismo y lo que encontraron, re-impulsa con UNA bala concreta y cierra con acción. El scope se cubre cuando el cliente reconoció el punto y contestó avanzando."},"closing":{"message":"FFF completo: entendiste cómo se sentía, le dijiste que no estaba solo y lo que encontraron otros, le diste una bala y le propusiste el siguiente paso. Ni te defendiste ni lo evadiste. Así se les habla a los que te hablan en serio. Vamos al detalle.","message_incomplete":"Ahí lo dejamos, ya vi cómo manejas lo que de verdad le preocupa. Vamos al desglose."}},"version":"1.1.1","i_do_type":"demo","failure_criteria":[{"id":"se_pone_defensivo","regla_id":"objection.discutir","severity":"critical","description":"Contradice o corrige al cliente (no, no esta caro; usted no entiende) o se justifica a la defensiva: confirma sus miedos y lo atrinchera. Dar datos sin decirle que se equivoca no es esto."},{"id":"air_a_objecion","regla_id":"objection.air_a_objecion","severity":"critical","description":"Aplica AIR a la objeción real: la valida y cambia de tema sin responderla. El cliente lo nota (no me cambió el tema) y la confianza se rompe — la herramienta del bloqueo usada donde tocaba respuesta de verdad."},{"id":"vacia_el_cargador","regla_id":"objection.vacia_el_cargador","severity":"major","description":"Suelta dos o mas balas en la misma respuesta a la objecion, en vez de una sola antes de cerrar: abruma, ninguna pega, y se queda sin municion."},{"id":"salta_la_bala","regla_id":"objection.cierra_sin_bala","severity":"major","description":"Atiende la objeción y vuelve a pedir la decisión sin dar antes ninguna bala que suba el impulso: le pide una decisión al cliente en el punto más bajo de su ánimo."},{"id":"bala_se_cae","regla_id":"present.bala_generica","severity":"critical","description":"Su bala no aguanta el ¿a poco?: cuando el cliente pide lo concreto, no lo da, la infla o cambia la historia.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"descuento_de_panico","regla_id":"close.descuento_de_panico","severity":"major","description":"Baja el precio, regala o mejora la oferta porque el cliente dijo que esta caro o dudo, sin pedir nada a cambio. Un descuento a cambio de algo (mas volumen, pago de contado) o el que ya era parte de la oferta no es esto."},{"id":"monologo","regla_id":"monologo","severity":"minor","description":"Responde la objeción con un bloque largo: FFF es quirúrgico, no un discurso."}],"success_criteria":[{"id":"objections.reframe","weight":0.4,"regla_id":"objection.fff","description":"Los cinco pasos de FFF ante la objeción: entiende cómo se siente sin discutir, le dice que otros sintieron lo mismo, lo que encontraron, re-impulsa con una bala y cierra con acción (el siguiente paso concreto). Si falta un paso, está a medias."},{"id":"objections.no_defensivo","weight":0.3,"regla_id":"objection.discutir","description":"Cero defensa y cero evasión: no discute, no se justifica atropellado, no se ofende, y NO aplica AIR (la objeción se responde, nunca se ignora con cambio de tema). Su calidez es idéntica antes y después de la objeción."},{"id":"objections.bullet_theory","weight":0.3,"regla_id":"present.balas","description":"Su re-impulso es UNA bala concreta, que responde a la objeción que puso el cliente: nunca argumentos apilados ni aire declarativo, y aguanta el ¿a poco?"}]}$g$::jsonb WHERE id = '5.8' AND practice_script->>'version' = '1.1.0';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.0.0 Nodo nuevo. El corazon del Mundo 5. El espejo distingue tres calidades: discutir cierra al cliente, atravesar-sin-bala produce desgano medible, y el circuito completo recupera el animo. Ensena en carne propia por que el paso intermedio no es opcional. v2.1.0 (mensaje 137): el espejo ya no rechaza una bala ya dicha si ahora la conecta con la objeción (como dice objection.circulo_de_cierre y la tarjeta 3); solo la repetida tal cual o la vaga no cuentan. v2.2.0 (mensaje 138, Emilio 6-nov): la bala la escoge el vendedor; una ya dicha, aun tal cual, también re-impulsa (ratifica y da seguridad), aunque pegue menos. «Lo que encontramos» de FFF no es la bala. Sale bala_repetida.","scope":{"skills_in_focus":["objections.circulo_cierre","objections.bullet_theory","flow.close_with_action"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Cuenta tres movimientos después de la objeción. Uno: la atravieso sin discutir.\n\nDos, y este es el que todos se saltan: meto una bala, la que escojo para volver a subirle el ánimo. Tres: cierro con acción.\n\nSi me salto el dos, le estoy pidiendo una decisión a alguien desanimado.","first_message":"Entiendo perfecto, y tiene razón en cuidar el flujo. Mi último cliente estaba igual, y lo que encontramos fue que, arrancando con la mitad del pedido, se movía solo y el segundo ya salía de lo vendido.\n\nY algo más: en su primer pedido le respetamos el precio por noventa días, aunque suba la lista.\n\nEntonces, ¿arrancamos con media caja o con caja completa?"},"you_do":{"prompt":"Eres el dueno de un negocio. Ya te presentaron y te intereso, pero tienes UNA preocupacion real: elige una al azar y quedate con ella — el flujo esta apretado este mes / ya te fallo un proveedor antes y quedaste mal con tus clientes / no sabes si se va a vender / tu socio o tu esposa participa en las decisiones de compra. TU REGLA PRINCIPAL: sacas tu preocupacion cuando el vendedor intente cerrar, y despues reaccionas segun COMO la maneje. Si DISCUTE o minimiza tu preocupacion, te cierras y ya no compras. Si la atraviesa bien PERO cierra de inmediato sin darte ninguna bala (lo que encontraron otros clientes no cuenta como bala), contestas con desgano: pues si, dejeme lo pienso / ahorita no se, luego le digo. Tecnicamente te respondio, pero tu animo quedo abajo y no vas a decidir desde ahi. Si la atraviesa bien, te da UNA BALA —un hecho positivo concreto, nuevo o que ya te habia dicho— y despues cierra con una pregunta concreta del siguiente paso, tu animo se recupera visiblemente y contestas esa pregunta avanzando. Si te repite tal cual algo que ya te habia dicho, si cuenta: te confirma que es verdad y te da seguridad, aunque te pega menos que una que le hable a tu preocupacion; contestas avanzando, con menos entusiasmo. Si la bala es vaga, no cuenta: reaccionas con desgano. NUNCA saques una segunda objecion en este ejercicio: es una sola, una vuelta. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor completa el circuito ante una objeción: la atraviesa sin discutir, re-impulsa con UNA bala (la que escoja: nueva o ya dicha) y cierra con una acción concreta. El scope se cubre cuando el cliente recupera el ánimo y responde avanzando al siguiente paso."},"closing":{"message":"Esa es la vuelta completa. Atravesaste, volviste a subir el impulso con una bala y cerraste. Fíjate en que, sin el paso de en medio, le habrías pedido una decisión a alguien desanimado. Vamos al detalle.","message_incomplete":"Ahí lo dejamos. Vamos al desglose y te digo cómo quedó la vuelta."}},"version":"2.2.0","i_do_type":"demo","failure_criteria":[{"id":"salta_la_bala","regla_id":"objection.cierra_sin_bala","severity":"critical","description":"Atraviesa la objecion y cierra de inmediato, sin re-impulsar. Le pide una decision al cliente en el punto mas bajo de su animo, y recibe un lo voy a pensar.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"discute_la_objecion","regla_id":"objection.discutir","severity":"critical","description":"Discute, minimiza o intenta demostrar que la preocupacion del cliente no es valida. Ganar la discusion es perder la venta."},{"id":"no_cierra","regla_id":"objection.circulo_de_cierre","severity":"major","description":"Atraviesa y re-impulsa pero nunca vuelve a pedir la decision. Se quedo a un paso."}],"success_criteria":[{"id":"objections.circulo_cierre","weight":0.35,"regla_id":"objection.circulo_de_cierre","description":"Atraviesa la objecion sin discutir ni minimizar, usando validacion genuina antes de responder. El cliente debe sentir que lo escucharon, no que le ganaron un argumento."},{"id":"objections.bullet_theory","weight":0.35,"regla_id":"present.balas","description":"Después de atravesar, mete UNA bala concreta, la que escoja para volver a subir el impulso: un hecho positivo que no había dicho, o uno ya dicho. Una ya dicha cuenta aunque la repita tal cual; pega más si la conecta con la objeción («por eso le sale más barato…»). Lo que encontraron otros clientes, en FFF, no es la bala. Este es el paso que casi todos se saltan."},{"id":"flow.close_with_action","weight":0.3,"regla_id":"close_with_action","description":"Cierra con una pregunta o accion concreta del siguiente paso, cuya respuesta solo tiene sentido si el cliente avanza. Nada de preguntar si quiere, si le parece o si lo va a pensar."}]}$g$::jsonb WHERE id = '5.10' AND practice_script->>'version' = '2.1.0';

UPDATE public.nodes SET practice_script = $g${"notes":"La cadena de dos con espejo de temple: el Actor detecta el desánimo textual (el drenaje real que las cadenas producen en el campo) y lo verbaliza. repite_bala entrena que cada motivo pide SU munición. El par de objeciones es aleatorio entre tres combinaciones — seis órdenes posibles de práctica. v1.2.0 (mensaje 137): cada objeción con RRR o con FFF (el Cerebro: fuera del nodo que enseña una herramienta, sirven las dos); el espejo cuenta el cargador desde dos argumentos (como la falla) y acepta una bala ya dicha si ahora la conecta con la objeción nueva; el ejemplo ya no le pide al cliente que pruebe y compare (4.15). v1.3.0 (mensaje 138, Emilio 6-nov): la bala la escoge el vendedor; una ya dicha, aun tal cual, también re-impulsa (ratifica y da seguridad), aunque pegue menos. «Lo que encontramos» de FFF no es la bala. Sale repite_bala.","scope":{"skills_in_focus":["objections.reframe","objections.bullet_theory","impulse.indiferencia","objections.circulo_cierre"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":12,"max_duration_seconds":300,"min_turns_before_evaluation":4},"phases":{"i_do":{"briefing":"Ahora en serie: resuelvo una objeción... y llega la siguiente.\n\nFíjate en dos cosas: cada una recibe SU bala —la que le conviene a esa objeción— y mi ánimo no se mueve: la segunda objeción me encuentra igual de sereno que la primera.","first_message":"«Está caro.» Le repito lo que me dijo, le hago la cuenta por servicio —esa es mi primera bala— y cierro: «¿Le armo la primera caja para el martes o para el jueves?».\n\n«Sí, pero es que ya tengo proveedor de años...» Recibo: «Entiendo cómo se siente, los años de relación valen. Al taller del Puente le pasaba igual, y lo que encontró fue que no tenía que dejar a nadie».\n\nBala dos, distinta: «Y como paso cada martes, lo que se le acabe en la semana lo tiene el martes siguiente». Cierro: «¿Arrancamos este martes o el que sigue?».\n\nDos objeciones, dos balas distintas, y el mismo ánimo en las dos. La cadena se gana con dosificación y temple."},"you_do":{"prompt":"Eres el dueño de un negocio interesado de verdad — la presentación conectó tu dolor (elígelo y menciónalo al abrir) — pero eres de los que se aseguran ANTES de decidir: tu proceso natural es sacar TODAS tus dudas, una por una. GUION DE LA CADENA: tienes DOS objeciones reales que vas a soltar EN SERIE (elige el par al azar): [está caro + ya tengo proveedor] o [ya tengo proveedor + déjeme consultarlo con mi socio] o [está caro + déjeme consultarlo]. Sueltas la PRIMERA tras tu línea inicial. REGLA DE LA CADENA: cuando el vendedor resuelve bien la primera (la atiende sin discutir, con RRR o con FFF, y te da una bala concreta), NO cedes todavía — reconoces el punto (bueno, eso sí...) e inmediatamente sueltas la SEGUNDA (sí pero es que además...). Solo cuando AMBAS están bien resueltas, cedes y avanzas la decisión. ESPEJOS (aplican a cada objeción): defensa → te atrincheras; evasión-AIR → lo señalas; bala vaga → la retas con ¿a poco?; cargador vaciado (dos o más argumentos juntos) → te abruma y la cadena se alarga; la MISMA bala de la primera para la segunda objeción → cuenta: te confirma lo que ya te dijo, aunque te convence menos que una que le hable a tu nueva preocupación. ESPEJO DE TEMPLE: si detectas frustración, desánimo o sequedad creciente del vendedor ante la segunda objeción (respuestas más cortas, tono resignado, muletillas de fastidio), lo mencionas y te enfrías: ¿ya se cansó de mis preguntas, verdad? Tu techo: decisión avanzada con condición práctica tras la cadena completa. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor sostiene una cadena de DOS objeciones reales consecutivas: atiende cada una sin discutir, con RRR o con FFF, y le da SU propia bala, la que escoja para esa objeción (sin apilarlas), mantiene la calidez y serenidad idénticas de la primera a la última (cero frustración textual ante la cadena), y tras resolver ambas avanza la decisión con naturalidad. El scope se cubre cuando la segunda objeción quedó resuelta y el cliente avanzó."},"closing":{"message":"Dos objeciones en cadena, dos balas distintas, y tu ánimo sin moverse un milímetro. Así se ve un arsenal bien dosificado en manos serenas. Vamos al detalle.","message_incomplete":"Hasta aquí la sesión. Ya tengo lo que necesito. Vamos al desglose y te digo cómo quedó tu munición."}},"version":"1.3.0","i_do_type":"demo","failure_criteria":[{"id":"se_pone_defensivo","regla_id":"objection.discutir","severity":"critical","description":"La defensa aparece en cualquier eslabón de la cadena."},{"id":"se_desanima_en_cadena","regla_id":"objection.se_desanima","severity":"major","description":"La segunda objeción le drena el ánimo: respuestas más cortas, tono resignado o fastidio detectable — el cliente lo nota (¿ya se cansó de mis preguntas?)."},{"id":"vacia_el_cargador","regla_id":"objection.vacia_el_cargador","severity":"major","description":"Suelta dos o mas balas en una misma respuesta de la cadena."},{"id":"air_a_objecion","regla_id":"objection.air_a_objecion","severity":"critical","description":"Evade cualquiera de las objeciones con cambio de tema."},{"id":"bala_se_cae","regla_id":"present.bala_generica","severity":"critical","description":"Cualquier bala de la cadena que sea aire o que se caiga ante el ¿a poco?.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"descuento_de_panico","regla_id":"close.descuento_de_panico","severity":"major","description":"Baja el precio, regala o mejora la oferta porque el cliente dijo que esta caro o dudo, sin pedir nada a cambio. Un descuento a cambio de algo (mas volumen, pago de contado) o el que ya era parte de la oferta no es esto."},{"id":"monologo","regla_id":"monologo","severity":"minor","description":"Bloques largos que alargan la cadena."}],"success_criteria":[{"id":"objections.reframe","weight":0.3,"regla_id":"objection.fff","description":"Cada objeción de la cadena se atiende sin discutir, con RRR (la repite, responde concreto, retoma) o con FFF (cómo se siente, otros sintieron lo mismo, lo que encontraron), y avanza. Ninguna queda a medias."},{"id":"objections.bullet_theory","weight":0.3,"regla_id":"present.balas","description":"Dosificación bajo presión: UNA bala por objeción, la que el vendedor escoja para esa objeción (puede ser una ya dicha), sin apilar argumentos, y sus balas aguantan el ¿a poco?"},{"id":"impulse.indiferencia","weight":0.2,"regla_id":"impulse.indiferencia","description":"El temple de la cadena: calidez y serenidad idénticas ante la primera y la segunda — sin frustración, sin sequedad creciente, sin tono de fastidio. SW3 sostenido cuando el sí se aleja un turno más."},{"id":"objections.circulo_cierre","weight":0.2,"regla_id":"objection.circulo_de_cierre","description":"Despues de atravesar cada objecion, re-impulsa con UNA bala (la que escoja: una que no habia dicho o una ya dicha) y vuelve a pedir la decision con accion. Lo que encontraron de FFF no es la bala."}]}$g$::jsonb WHERE id = '5.12' AND practice_script->>'version' = '1.2.0';

UPDATE public.nodes SET practice_script = $g${"notes":"El nodo del silencio: el cliente delibera de verdad (pausas pensativas que NO son rechazo) y decide a favor si el vendedor aguanta. llena_el_silencio es critical: es EL tema. v1.1.0 (mensaje 137, Emilio 5-nov): aguantar es lo correcto, pero no garantiza el sí; en algunas sesiones el cliente pone una objeción aunque el vendedor haya aguantado bien, y eso no es falla del vendedor: se trabaja como objeción. Sale la segunda ola de reaseguro (sobre_reaseguro), que calificaba la consolidación del mundo 6. v1.1.1 (mensaje 138, Emilio 6-nov): la bala la escoge el vendedor; una ya dicha, aun tal cual, también re-impulsa (ratifica y da seguridad), aunque pegue menos. «Lo que encontramos» de FFF no es la bala.","scope":{"skills_in_focus":["closing.sin_miedo","impulse.indiferencia"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":8,"max_duration_seconds":180,"min_turns_before_evaluation":2},"phases":{"i_do":{"briefing":"Te voy a enseñar el momento donde más ventas se suicidan: el silencio después del cierre. Escucha lo que hago después de preguntar — NADA.\n\nY escucha lo que el miedo le hace hacer a otros.","first_message":"Cierro: ¿Le armo las 5 cajas o el combo de 8? — Y el cliente se queda callado.\n\nPiensa. El silencio pesa...\n\ny aquí es donde el vendedor con miedo se suicida: Bueno, si le parece mucho también hay de 3... o si quiere lo piensa y...\n\n— ¡Acaba de deshacer su propio cierre! El cliente ni había dicho nada.\n\nYo, en cambio: pregunto... y me callo.\n\nTres segundos. Cinco.\n\nLos que sean. El que habla primero después del cierre, pierde — y no vas a ser tú."},"you_do":{"prompt":"Eres el dueño de un negocio convencido pero DELIBERATIVO: la conversación fue buena, el valor está claro, y cuando algo te convence... igual te tomas tu tiempo — eres de los que piensan con calma antes de soltar el sí. GUION: la conversación está madura (tu primera línea lo muestra: recapitulas el valor con un pues la verdad sí me late, la cuenta sale...). Cuando el vendedor cierre, tu MECÁNICA CENTRAL se activa: (1) PRIMERA PAUSA — respondes con duda pensativa, NO con rechazo: Mmm... — o — Déjeme ver... — estás pensando de verdad, sopesando. (2) REGLA DEL SILENCIO: si el vendedor AGUANTA tu pausa — no agrega nada, no se retracta, no descuenta, a lo sumo un silencio cómodo o una frase mínima de acompañamiento (tómese su tiempo) — tu deliberación madura a favor: Va. Vamos a hacerlo. ¿Dijo que el lunes llega? y eliges. EXCEPCIÓN: al empezar decide al azar si hoy eres de los que, aunque el vendedor aguante bien, terminan con una objeción (una de cada tres sesiones). Si lo eres, después de tu pausa dices algo como: déjeme pensarlo, este mes ando corto. No es porque lo haya hecho mal: así eres hoy. Si el vendedor la atiende bien (te entiende o te la repite, te da una bala y vuelve a cerrar con opciones, sin presionarte), escoges. (3) Si el vendedor LLENA EL SILENCIO — se retracta (bueno, si le parece mucho...), descuenta por pánico, agrega opciones más chicas, o re-pregunta con puerta al no (¿o mejor lo piensa?) — tu deliberación se CONTAMINA: la duda que no tenías aparece (pues ahora que lo dice... déjeme pensarlo bien) y la decisión se aplaza. (4) Si tras aguantar bien tú decides, y él confirma con naturalidad, sellado.","objective":"El vendedor cierra asumido y AGUANTA el silencio deliberativo del cliente: tras su pregunta de cierre, no agrega, no se retracta, no descuenta ni reabre la decisión — sostiene la pausa con serenidad (silencio o acompañamiento mínimo) hasta que el cliente decide. Si el cliente pone una objeción después de pensarlo, la trabaja como objeción: la atiende sin presionar, da una bala y vuelve a cerrar. El scope se cubre cuando el cliente decidió, después de su pausa o después de que el vendedor atendió su objeción."},"closing":{"message":"Preguntaste... y te callaste. El silencio pesó — y lo aguantaste. Y el que decidió fue él, solito, con la decisión más firme que existe: la propia. Eso es cerrar sin miedo. Vamos al detalle.","message_incomplete":"Ahí lo dejamos. Vamos al desglose y te digo qué tanto aguantaste el silencio."}},"version":"1.1.1","i_do_type":"demo","failure_criteria":[{"id":"llena_el_silencio","regla_id":"close.llena_el_silencio","severity":"critical","description":"Despues de pedir la decision y antes de que el cliente decida, se retracta (si es mucho, pueden ser cinco), la suaviza (o si quiere lo piensa), mete descuentos o argumentos nuevos, o se contesta solo. Contestar una pregunta del cliente no es esto. Si el vendedor aguantó y aun así el cliente pone una objeción, eso no es falla del vendedor: atenderla tampoco es esto.","severity_override":{"razon":"escalada: habilidad espejo del nodo","default":"major"}},{"id":"abre_puerta_al_no","regla_id":"close.mal_cierre","severity":"major","description":"Su cierre inicial ya llega con puerta (¿le interesa?) — el silencio que sigue es de otro examen.","severity_override":{"razon":"incidental: fuera del foco del nodo","default":"critical"}},{"id":"persigue","regla_id":"close.persigue","severity":"major","description":"Presiona la deliberación: ándele, anímese, ¿entonces qué? — el silencio del cliente no es invitación a empujar."},{"id":"salta_la_bala","regla_id":"objection.cierra_sin_bala","severity":"major","description":"Atiende la objeción y vuelve a pedir la decisión sin dar antes ninguna bala que suba el impulso: le pide una decisión al cliente en el punto más bajo de su ánimo."},{"id":"monologo","regla_id":"monologo","severity":"minor","description":"Cualquier bloque largo en la fase de deliberación."}],"success_criteria":[{"id":"closing.sin_miedo","weight":0.6,"regla_id":"close.aguanta_silencio","description":"Cierra con claridad y sostiene el silencio deliberativo: tras su pregunta de cierre no se retracta, no descuenta, no agrega opciones menores ni reabre la decisión — sus turnos durante la pausa son silencio o acompañamiento mínimo y sereno. Contestar una pregunta del cliente no rompe el silencio. Si el cliente pone una objeción después de pensarlo, la atiende sin perder la calma y vuelve a cerrar."},{"id":"impulse.indiferencia","weight":0.4,"regla_id":"impulse.indiferencia","description":"La serenidad SW3 sostiene el momento: cero ansiedad textual durante la deliberación del cliente, cero necesidad de acelerar su decisión — cálido, presente y en calma con cualquier resultado."}]}$g$::jsonb WHERE id = '5.13' AND practice_script->>'version' = '1.1.0';

UPDATE public.nodes SET practice_script = $g${"notes":"v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El Actor tiene instruccion de NUNCA cancelar el pedido base: eso obliga al vendedor a distinguir que es lo que de verdad esta cerrando. El espejo castiga reabrir el pedido base con confusion del cliente. v2.1.0 (mensaje 137, Emilio 5-nov): después de la alternativa se aguanta, como enseña la 5.13. Sale silencio_despues_del_cierre, que castigaba lo contrario. Si el cliente dice «déjeme pensarlo», no es castigo: es una objeción, y se trabaja sin tocar el pedido base. v2.1.1 (mensaje 138, Emilio 6-nov): la bala la escoge el vendedor; una ya dicha, aun tal cual, también re-impulsa (ratifica y da seguridad), aunque pegue menos. «Lo que encontramos» de FFF no es la bala.","scope":{"skills_in_focus":["closing.cerrar_incremento","closing.cierre_asumido","flow.close_with_action"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":10,"max_duration_seconds":210,"min_turns_before_evaluation":3},"phases":{"i_do":{"briefing":"Fíjate en que NO vuelvo a cerrar el pedido base. Ese ya está: no lo toco, no lo pongo en duda.\n\nCierro únicamente lo que agregué. Y lo cierro asumiendo, con una alternativa donde las dos opciones me sirven.\n\nY en cuanto lo digo, me callo.","first_message":"Entonces le queda lo de siempre, más las cajas de más que platicamos.\n\n¿Esas se las mando en la misma entrega o prefiere que se las deje aparte?"},"you_do":{"prompt":"REGLA NUMERO CERO: eres un cliente CONTENTO, sin quejas. Ya le diste tu pedido de siempre al vendedor y eso NO esta en duda: pase lo que pase en esta conversacion, ese pedido va. No lo canceles ni lo pongas en duda nunca.\n\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Adopta el tipo de negocio y las familias del contexto de la empresa. En esta conversacion el vendedor te acaba de proponer AGREGAR algo: mas cantidad de lo que ya llevas, o una familia nueva.\n\nCOMO REACCIONAS AL CIERRE DEL INCREMENTO:\n\nSI TE PREGUNTA SI QUIERES (le parece bien?, como lo ve?, quiere que se lo ponga?): contestas dejeme lo pienso o la proxima quincena lo vemos. No es que no te interese: es que te dio la salida y la tomaste.\n\nSI VUELVE A CERRAR EL PEDIDO BASE o lo pone en duda (entonces si le mando lo de siempre?): te confundes y te pones a revisar todo otra vez, incluso lo que ya estaba resuelto.\n\nSI ASUME EL INCREMENTO Y TE DA UNA ALTERNATIVA (se las mando en la misma entrega o aparte?, le pongo las cinco o arrancamos con tres?): contestas la pregunta con naturalidad y con eso queda cerrado. EXCEPCION: al empezar decide al azar si hoy, aunque el vendedor lo haga bien, dudas del incremento (una de cada tres sesiones). Si es asi, en lugar de escoger dices algo como: dejeme pensarlo, no se si se me vaya a mover tanto. No es porque lo haya hecho mal: asi eres hoy. Es una objecion: si el vendedor la atiende bien (te la repite o te entiende, te da una bala y vuelve a cerrar con una alternativa, sin tocar el pedido de siempre), escoges.\n\nSI TE PRESIONA o insiste de mas: te incomodas y te echas para atras con el incremento, aunque el pedido base siga.\n\nResponde en 1 o 2 frases, natural.","objective":"El vendedor cierra únicamente el incremento —lo que se agrega al pedido base—, asumiéndolo y ofreciendo una alternativa donde ambas opciones le sirven, sin volver a poner en duda el pedido de siempre, y aguanta después de preguntar. Si el cliente pone una objeción, la atiende, da una bala y vuelve a cerrar con una alternativa. El scope se cubre cuando el cliente responde a la alternativa y el incremento queda confirmado."},"closing":{"message":"Eso es cerrar el incremento. No volviste a vender lo que ya estaba, no le preguntaste si quería, y le diste una alternativa donde las dos te servían. Vamos al detalle.","message_incomplete":"Ahí lo dejamos. Vamos al desglose y te digo cómo quedó ese cierre."}},"version":"2.1.1","i_do_type":"demo","failure_criteria":[{"id":"pregunta_si_quiere","regla_id":"close.mal_cierre","severity":"critical","description":"Pide la decision con una pregunta que se contesta con un no o un dejeme pensarlo: de interes (le interesa?), de opinion (que le parece?) o de si o no sobre la compra (se lo mando?, le aparto 10 cajas?). Todas son igual de graves."},{"id":"reabre_el_pedido_base","regla_id":"close.reabre_pedido_base","severity":"major","description":"Vuelve a confirmar o poner en duda el pedido de siempre. Reabre algo que ya estaba cerrado e invita al cliente a revisar toda la orden."},{"id":"salta_la_bala","regla_id":"objection.cierra_sin_bala","severity":"major","description":"Atiende la objeción y vuelve a pedir la decisión sin dar antes ninguna bala que suba el impulso: le pide una decisión al cliente en el punto más bajo de su ánimo."},{"id":"presiona","regla_id":"close.persigue","severity":"major","description":"Insiste de mas despues de haber cerrado. Con un cliente de cartera la presion cuesta la relacion, que vale mas que el incremento."}],"success_criteria":[{"id":"closing.cerrar_incremento","weight":0.4,"regla_id":"close.cierra_solo_incremento","description":"Cierra UNICAMENTE lo que se agrega — las cantidades de mas o la familia nueva — sin volver a poner en duda el pedido base. Reabrir el pedido de siempre no cumple: ese ya estaba resuelto y ponerlo en la mesa otra vez invita al cliente a revisarlo todo."},{"id":"closing.cierre_asumido","weight":0.35,"regla_id":"close.alternativa","description":"Asume el incremento y ofrece una alternativa donde las dos opciones le sirven al vendedor. Preguntar si lo quiere, si le parece bien o como lo ve, no cumple: invita al lo voy a pensar."},{"id":"flow.close_with_action","weight":0.25,"regla_id":"close_with_action","description":"La pregunta de alternativa ES el cierre con acción: la respuesta del cliente confirma el incremento sin que se lo hayan pedido explícitamente. Después de preguntar, aguanta. Si el cliente pone una objeción, la atiende y vuelve a cerrar con una alternativa."}]}$g$::jsonb WHERE id = '5.14' AND practice_script->>'version' = '2.1.0';

UPDATE public.nodes SET practice_script = $g${"notes":"BOSS del Mundo 5 contra el desconfiado d5 — el examen integrador de las dos especies del no: bloqueo (AIR) y objeciones (reframe+balas) en la misma conversación. Mecánicas distintivas: la minimización del dolor (capa extra sobre M3: no se discute, se guarda para la presentación — Emilio, 2-nov-2026), la objeción de confianza PERSONAL (la más difícil de no tomar como ataque), y la condición de protección que se honra en vez de pelearse. Su rendición característica — le tomo la palabra y lo apunto — es la victoria realista: confianza a prueba, no fe ciega. v1.1.0 (oct-2026, Emilio): el boss de El Cierre califica con los nombres de la doctrina: RRR para la objeción menor, FFF para la de confianza, balas y círculo de cierre. \"Sin defensa\" sale de los criterios porque ya es falla crítica. v1.3.0 (mensaje 137): pelea_la_condicion se califica con close.asume_con_presion (ignorar un cambio que el cliente pidió es presionar); se agrega abre_puerta_al_no (cerrar con «¿le interesa?» es falla grave también en el jefe); el objetivo ya no dice «desmonta su minimización» (no se discute: se usa en la presentación); el prompt ya no cita números de nodo viejos. v1.3.1 (mensaje 138, Emilio 6-nov): la bala la escoge el vendedor; una ya dicha, aun tal cual, también re-impulsa (ratifica y da seguridad), aunque pegue menos. «Lo que encontramos» de FFF no es la bala.","scope":{"skills_in_focus":["blocks.air","objections.rrr_objeciones","objections.reframe","objections.bullet_theory","objections.circulo_cierre","discovery.dolor_real","closing.cierre_asumido"],"out_of_scope_behavior":"redirect"},"limits":{"max_turns":20,"max_duration_seconds":480,"min_turns_before_evaluation":8},"phases":{"you_do":{"prompt":"Eres el dueño de un negocio de perfil DESCONFIADO EXTREMO: años de vendedores que prometieron y fallaron te dejaron un escudo grueso — no eres grosero, eres impenetrable por default. GUION COMPLETO: (1) BLOQUEO de entrada en tu primera o segunda respuesta: mire, le voy a ahorrar tiempo — no me interesa. Espejo AIR estándar: bien atravesado sigues (seco); debatido, te cierras más. (2) DOLOR oculto (elige: proveedor que te falla quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — por capas, con pista del aunque, y una capa EXTRA de desconfianza: al revelarlo, lo minimizas de inmediato (pero bueno, así es esto, todos fallan igual). Si el vendedor te lo discute o insiste en que lo reconozcas, te pones a la defensiva. Si lo deja pasar y sigue, está bien: no se lo pidas. Lo que sí te mueve es que en la presentación te enseñe con TUS números lo que pierdes. (3) PRESENTACIÓN: toda promesa sin ancla dispara tu cicatriz (eso mismo me dijo el anterior); solo el valor conectado con TU dolor y TUS números te abre. (4) CADENA DE OBJECIONES — tu examen final, DOS en serie tras la presentación: primera siempre: ¿y por qué le voy a creer a usted, si el anterior me dijo lo mismo y me dejó plantado? (objeción de confianza — pide bala SOBRE ÉL: constancia concreta, referencia de la zona con nombre). Segunda: una objeción MENOR y común, al azar: está caro / el día de entrega no me acomoda. Se atiende con RRR: si te la repite, te responde concreto y sigue, la sueltas; si se pone a discutirla, te cansas. Espejos completos de las objeciones: defensa te atrinchera, evasión la señalas, bala vaga la retas (¿como quién? voy a ir a preguntarle, ¿eh?), cargador vaciado te abruma, bala repetida te convence menos que una nueva, pero cuenta. (5) Si TODO se sostuvo: tu rendición es característica — está bien... pero le voy a tomar la palabra de todo lo que dijo, ¿eh? Lo apunto. — y avanzas con UNA condición de protección (pedido chico de prueba / por escrito / referencia confirmada antes). Deliberación final con pausa: si el vendedor la aguanta, decides; si la llena (se retracta, descuenta o te empuja), vuelves a dudar. Tu techo: trato de prueba cerrado, nunca confianza plena — esa se gana en meses, no en una visita. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.","objective":"El vendedor completa la conversación con el desconfiado extremo: atraviesa el bloqueo con AIR, excava el dolor sin discutirle la minimización (la usa en la presentación, con sus números), presenta sin una sola promesa sin ancla, sostiene la cadena de dos objeciones — la de confianza personal con bala concreta sobre sí mismo, y la segunda con su munición propia — con temple idéntico, y cierra asumido aceptando la condición de protección del cliente, aguantando la deliberación final. El scope se cubre con el trato de prueba cerrado."},"closing":{"message":"El hombre que no le cree a nadie te acaba de tomar la palabra — y la apuntó. Atravesaste su bloqueo, desmontaste su resignación, y cada bala tuya aguantó su lupa. No ganaste su confianza completa: ganaste algo mejor — la oportunidad de demostrarla. Así maneja al más duro del campo. Vamos al desglose del mundo.","message_incomplete":"Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose."}},"version":"1.3.1","i_do_type":"demo","failure_criteria":[{"id":"se_pone_defensivo","regla_id":"objection.discutir","severity":"critical","description":"La objeción personal lo hiere y se defiende — el desconfiado confirma su tesis y se cierra para siempre."},{"id":"bala_se_cae","regla_id":"present.bala_generica","severity":"critical","description":"Cualquier bala o promesa que se cae cuando el desconfiado pide lo concreto (¿como quién? voy a ir a preguntarle, ¿eh?) — este arquetipo no da segundas oportunidades.","severity_override":{"razon":"boss: escalada","default":"major"}},{"id":"promesa_grandilocuente","regla_id":"present.bala_generica","severity":"critical","description":"Promesas sin ancla ante la cicatriz — eso mismo me dijo el anterior, y la sesión retrocede.","severity_override":{"razon":"boss: escalada","default":"major"}},{"id":"air_a_objecion","regla_id":"objection.air_a_objecion","severity":"critical","description":"Evade cualquier objeción de la cadena con cambio de tema."},{"id":"abre_puerta_al_no","regla_id":"close.mal_cierre","severity":"critical","description":"Pide la decisión con una pregunta que se contesta con un no o un déjeme pensarlo: de interés (¿le interesa?), de opinión (¿qué le parece?) o de sí o no sobre la compra (¿se lo mando?)."},{"id":"pelea_la_condicion","regla_id":"close.asume_con_presion","severity":"major","description":"Pelea la condición de protección del cliente (empuja el pedido grande, resiste el por escrito) — la condición era el puente, y lo quemó."},{"id":"vacia_el_cargador","regla_id":"objection.vacia_el_cargador","severity":"major","description":"Bajo presion suelta dos o mas balas en una misma respuesta."},{"id":"llena_el_silencio","regla_id":"close.llena_el_silencio","severity":"major","description":"No aguanta la deliberación final."},{"id":"insiste_tras_dos","regla_id":"blocks.insistir_tras_dos_no","severity":"major","description":"Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}],"success_criteria":[{"id":"blocks.air","weight":0.15,"regla_id":"blocks.air","description":"El bloqueo de entrada atravesado con la secuencia completa — la distinción bloqueo/objeción ejecutada en ambas direcciones dentro de la misma conversación."},{"id":"objections.rrr_objeciones","weight":0.15,"regla_id":"objection.rrr","description":"La segunda objeción, menor y común (precio o entrega), atendida con RRR: la repite en sus términos, responde concreto, y retoma sin pausa."},{"id":"objections.reframe","weight":0.2,"regla_id":"objection.fff","description":"La objeción de confianza (¿por qué le voy a creer a usted?) recibida con FFF: sin herida ni defensa, entiende cómo se siente, otros sintieron lo mismo, lo que encontraron, con una bala concreta sobre sí mismo."},{"id":"objections.bullet_theory","weight":0.15,"regla_id":"present.balas","description":"Munición precisa bajo lupa: bala concreta SOBRE SÍ MISMO para la objeción de confianza (constancia, nombre, referencia), bala distinta para la segunda — todas aguantando el ¿como quién?"},{"id":"objections.circulo_cierre","weight":0.15,"regla_id":"objection.circulo_de_cierre","description":"Despues de atravesar cada objecion, re-impulsa con UNA bala (la que escoja: una que no habia dicho o una ya dicha) y vuelve a pedir la decision con accion. Lo que encontraron de FFF no es la bala."},{"id":"discovery.dolor_real","weight":0.1,"regla_id":"discovery.escalera_capas","description":"El dolor excavado por capas hasta que el cliente lo cuenta. Si lo minimiza (asi es esto, todos fallan igual), no se lo discute: lo guarda y lo usa en la presentacion con sus numeros."},{"id":"closing.cierre_asumido","weight":0.1,"regla_id":"close.alternativa","description":"Cierra asumido aceptando con gracia la condición de protección (pedido de prueba, por escrito) — la condición no se pelea: se honra como el puente de confianza que es."}]}$g$::jsonb WHERE id = '5.15' AND practice_script->>'version' = '1.3.0';

DO $chk$ BEGIN
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.8') IS DISTINCT FROM '894f61b05546719e5a000763a7bb8b55' THEN RAISE EXCEPTION 'el guion del 5.8 no quedó'; END IF;
